rows[851]={title={{16,989410225},"변이: 양"},description={"^transforms the enemy into a helpless sheep that cannot cast spells or attack and movement speed is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%% for up to ([%+%-]?%d[%d,.]* %a+)%.$","최대 \0312\031 동안 적의 모습을 무기력한 양으로 바꿔 주문을 시전하거나 공격할 수 없도록 만듭니다. 대상의 이동 속도가 \0311\031%만큼 감소합니다.",{0,1},{1,2}},aura={"^cannot cast, attack or cast spells and movement speed is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","공격 및 마법 시전 불가\010이동 속도 \0311\031%만큼 감소",{0},{1}}}
