rows[1022]={title={{18,149727582},"보호의 손길"},description={"^places a hand on a party or raid member, protecting them from all physical attacks for ([%+%-]?%d[%d,.]* %a+), but during that time they cannot attack or use physical abilities%. players may only have one hand on them per paladin at any one time%. cannot be used on a target with forbearance%. causes forbearance for ([%+%-]?%d[%d,.]* %a+)%.$","대상 파티원 혹은 공격대원을 \0311\031 동안 모든 물리 공격으로부터 보호합니다. 하지만 대상은 이 동안 공격을 하거나 물리 능력을 사용할 수 없으며, \0312\031 동안 참을성 상태가 됩니다. 성기사마다 하나의 대상에게 하나의 손길만 효력을 발휘합니다.\010\010참을성 상태인 대상에게는 사용할 수 없습니다.",{1,1},{1,2}},aura={{68,783837426},"물리 공격에 면역\010공격 및 물리 능력 사용 불가"}}
rows[1038]={title={{17,1446867265},"구원의 손길"},description={"^places a hand on the party or raid member, temporarily removing all their threat for ([%+%-]?%d[%d,.]* %a+)%. players may only have one hand on them per paladin at any one time%.$","파티원이나 공격대원에게 구원의 손길을 뻗어, \0311\031 동안 일시적으로 모든 위협 수준을 제거합니다. 성기사마다 하나의 대상에게 하나의 손길만 효력을 발휘합니다.",{1},{1}},aura={{31,175209119},"일시적으로 모든 위협 제거"}}
rows[1044]={title={{15,755687868},"자유의 손길"},description={"^places a hand on the friendly target, granting immunity to movement impairing effects for ([%+%-]?%d[%d,.]* %a+)%. players may only have one hand on them per paladin at any one time%.$","대상에게 자유의 손길을 걸어주어 \0311\031 동안 이동 방해 효과에 면역이 되도록 합니다. 성기사마다 하나의 대상에게 하나의 손길만 효력을 발휘합니다.",{1},{1}},aura={{37,766602927},"이동 방해 효과에 면역"}}
