rows[1066]={title={{12,417982666},"바다표범 변신"},description={"^shapeshift into aquatic form, increasing swim speed by ([%+%-]?%d[%d,.%+%-to –]*)%% and allowing the druid to breathe underwater%. also protects the caster from polymorph effects%. the act of shapeshifting frees the caster of movement impairing effects%.$","수중 생물로 변신합니다. 수영 속도가 \0311\031%만큼 증가하고 물속에서 숨을 쉴 수 있으며, 변이 효과에 면역이 됩니다.\010\010변신을 하면 이동 방해 효과에서 벗어납니다.",{0},{1}},aura={"^immune to polymorph effects%. increases swim speed by ([%+%-]?%d[%d,.%+%-to –]*)%% and allows underwater breathing%.$","변이에 면역\010수영 속도 \0311\031%만큼 증가 \010수중 호흡 가능",{0},{1}}}
rows[1079]={title={{3,1970221},"도려내기"},aura={"^bleeding for ([%+%-]?%d[%d,.%+%-to –]*) damage every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","\0312\031초마다 \0311\031의 출혈 피해",{0,0},{1,2}}}
rows[1090]={title={{5,1899776642},"수면"},description={"^puts the enemy target to sleep for up to ([%+%-]?%d[%d,.]* %a+)%. any damage caused will awaken the target%. only one target can be asleep at a time%. unreliable on targets above level 30%.$","적을 최대 \0311\031 동안 잠재웁니다. 대상이 피해를 입으면 깨어납니다. 한 번에 하나의 대상만 잠재울 수 있습니다. 30 레벨을 초과한 대상에겐 제대로 효과를 발휘하지 못합니다.",{1},{1}},aura={{7,1770695193},"수면 중"}}
rows[1098]={title={{13,427618961},"악마 지배"},aura={{9,626833890},"지배됨"}}
rows[1120]={title={{10,1536485946},"영혼 흡수"},description={"^drains the soul of the target, causing ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) sec and energizing one soul shard after it deals damage twice%. if the target dies and yields experience or honor, three soul shards are energized%. lasts ([%+%-]?%d[%d,.]* %a+)%. if the target is at or below ([%+%-]?%d[%d,.%+%-to –]*)%% health when drain soul deals damage, it deals ([%+%-]?%d[%d,.%+%-to –]*)%% additional damage and causes all of your other periodic affliction damage effects to instantly deal ([%+%-]?%d[%d,.%+%-to –]*)%% of their normal periodic damage%.$","적의 영혼을 흡수해 \0312\031초마다 \0311\031의 암흑 피해를 입히고 피해를 두 번 입힐 때마다 영혼의 조각을 1개씩 얻습니다. 대상이 죽어 경험치나 명예 점수를 받으면 영혼의 조각 3개를 얻습니다. \0313\031 동안 지속됩니다.\010\010영혼 흡수로 피해를 줄 때 대상의 생명력이 \0314\031% 이하이면, \0315\031%의 추가 피해를 입히고, 다른 모든 주기적인 고통 주문 효과가 주기적 피해량의 \0316\031%에 해당하는 피해를 즉시 입힙니다.",{0,0,1,0,0,0},{1,2,3,4,5,6}},aura={"^deals ([%+%-]?%d[%d,.%+%-to –]*) shadow damage and causes all of the warlock's other periodic affliction damage effects to instantly deal ([%+%-]?%d[%d,.%+%-to –]*)%% of their normal periodic damage, every ([%+%-]?%d[%d,.%+%-to –]*) seconds%.$","\0313\031초마다 \0311\031의 암흑 피해 및 다른 모든 주기적인 고통 주문 효과가 주기적 피해량의 \0312\031%에 해당하는 피해를 즉시 입힘",{0,0,0},{1,2,3}}}
rows[1121]={title={{8,1866442102},"휘감기"},description={"^the lair of fankriss the unyielding pulls the target into the path of nearby silithid hatchlings, rooting it for ([%+%-]?%d[%d,.]* %a+)%.$","주위에 있는 새끼 실리시드의 길로 대상을 잡아 끌어 \0311\031 동안 이동 불가 상태로 만듭니다.",{1},{1}},aura={{7,838998683},"이동 불가"}}
rows[1122]={title={{15,641390741},"지옥불정령 소환"},description={"^summons a meteor from the twisting nether, causing ([%+%-]?%d[%d,.%+%-to –]*) fire damage and stunning all enemy targets in the area for ([%+%-]?%d[%d,.]* %a+)%. an infernal rises from the crater, under the command of the caster for ([%+%-]?%d[%d,.]* %a+)%. the infernal deals strong area of effect damage, and will be drawn to attack targets near the impact point%.$","뒤틀린 황천으로부터 운석을 소환하여 선택한 지역의 모든 적에게 \0311\031의 화염 피해를 입히고 \0312\031 동안 기절시킵니다. 분화구에서 일어난 지옥불정령은 \0313\031 동안 흑마법사의 지배를 받습니다.\010\010지옥불정령은 강력한 광역 공격을 하며 소환 지점에서 가까운 대상을 공격합니다.",{0,1,1},{1,2,3}}}
rows[1126]={title={{16,784915423},"야생의 징표"},description={"^increases the friendly target's strength, agility, and intellect by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%. if target is in your party or raid, all party and raid members will be affected%.$","\0312\031 동안 아군 대상의 힘, 민첩성, 지능을 \0311\031%만큼 증가시킵니다.\010\010파티원이나 공격대원에게 시전하면 모든 파티원과 공격대원이 효과를 받습니다.",{0,1},{1,2}},aura={"^strength, agility, and intellect increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","힘, 민첩성, 지능 \0311\031%만큼 증가",{0},{1}}}
