rows[6921]={title={{17,524850782},"검은뿔 돌진"},description={"^increases the physical damage dealt by the caster by ([%+%-]?%d[%d,.%+%-to –]*) and speeds its movement by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%. also curses an enemy on the first successful hit, reducing the physical damage it deals by ([%+%-]?%d[%d,.%+%-to –]*), reducing the magical damage it deals by ([%+%-]?%d[%d,.%+%-to –]*), and increasing the physical damage it takes by ([%+%-]?%d[%d,.%+%-to –]*) for ([%+%-]?%d[%d,.]* %a+)%.$","\0313\031 동안 물리 공격력이 \0311\031만큼, 이동 속도가 \0312\031%만큼 증가합니다. 또한, 첫 공격 시 적에게 저주를 걸어 \0317\031 동안 물리 공격력을 \0314\031만큼, 마법 공격력을 \0315\031만큼 감소시키고 받는 물리 피해를 \0316\031만큼 증가시킵니다.",{0,0,1,0,0,0,1},{1,2,3,4,5,6,7}},aura={"^movement speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. physical damage dealt is increased by ([%+%-]?%d[%d,.%+%-to –]*)%.$","이동 속도 \0311\031%만큼 증가\010물리 공격력 \0312\031만큼 증가",{0,0},{1,2}}}
rows[6922]={title={{23,305518333},"검은뿔의 저주"},description={"^the spirits of the shadowhorn curse the target, reducing all damage dealt and increasing damage taken for ([%+%-]?%d[%d,.]* %a+)%.$","검은뿔의 영혼이 대상에 저주를 걸어 \0311\031 동안 공격력을 감소시키고 받는 피해를 증가시킵니다.",{1},{1}},aura={"^physical damage taken is increased by ([%+%-]?%d[%d,.%+%-to –]*)%. physical damage dealt is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%. magical damage dealt is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%.$","받는 물리 피해 \0311\031만큼 증가\010물리 공격력 \0312\031만큼 감소\010마법 공격력 \0313\031만큼 감소",{0,0,0},{1,2,3}}}
