rows[13159]={title={{18,186446383},"치타 무리의 상"},description={"^party and raid members within ([%+%-]?%d[%d,.%+%-to –]*) yards take on the aspects of a pack of cheetahs, increasing movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%%%. if you are struck under the effect of this aspect, you will be dazed for ([%+%-]?%d[%d,.]* %a+)%. only one aspect can be active at a time%.$","\0311\031미터 반경 내에 있는 파티원 혹은 공격대원이 치타의 상을 취해 이동 속도가 \0312\031%만큼 증가합니다. 이 동안 피해를 입으면 \0313\031 동안 멍해지게 됩니다. 한 번에 한 상만 취할 수 있습니다.",{0,0,1},{1,2,3}},aura={"^([%+%-]?%d[%d,.%+%-to –]*)%% increased movement speed%. dazed if struck%.$","이동 속도 \0311\031%만큼 증가\010피해 입을 시 멍해짐",{0},{1}}}
rows[13165]={title={{18,168464275},"매의 상"},description={"^the hunter takes on the aspects of a hawk, increasing ranged attack power by ([%+%-]?%d[%d,.%+%-to –]*)%%%. only one aspect can be active at a time%.$","매의 상을 취합니다. 원거리 전투력이 \0311\031%만큼 증가합니다. 한 번에 한 상만 취할 수 있습니다.",{0},{1}},aura={"^ranged attack power increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","원거리 전투력 \0311\031%만큼 증가",{0},{1}}}
