rows[13168]={title={{12,694430670},"닭의 분노"},description={"^increases the physical damage dealt by the chicken by ([%+%-]?%d[%d,.%+%-to –]*)%% and speeds the chicken's attack by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","\0313\031 동안 닭의 물리 공격력이 \0311\031%만큼, 공격 속도가 \0312\031%만큼 증가합니다.",{0,0,1},{1,2,3}},aura={"^physical damage dealt is increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. attack speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","물리 공격력 \0311\031%만큼 증가\010공격 속도 \0312\031%만큼 증가",{0,0},{1,2}}}
