rows[14516]={title={{6,446044},"일격"},description={{55,1777093787},"적을 강하게 내리쳐 추가 근접 피해를 입힙니다."}}
rows[14517]={title={{15,33528644},"성전사의 일격"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*)%% of normal weapon damage to an enemy and increases the holy damage it takes by ([%+%-]?%d[%d,.%+%-to –]*) per crusader strike%. can be applied up to 5 times%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","적에게 일반 무기 공격력의 \0311\031%에 해당하는 피해를 입히고, 성전사의 일격 효과 하나당 적이 입는 신성 피해를 \0312\031만큼 증가시킵니다. 최대 5번까지 중첩될 수 있습니다. \0313\031 동안 지속됩니다.",{0,0,1},{1,2,3}},aura={"^holy damage taken is increased by ([%+%-]?%d[%d,.%+%-to –]*)%.$","받는 신성 피해 \0311\031만큼 증가",{0},{1}}}
rows[14518]={title={{15,33528644},"성전사의 일격"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*)%% weapon damage to an enemy and increases the holy damage it takesper application of crusader strike%. can be applied up to 5 times%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","적에게 무기 공격력의 \0311\031%에 해당하는 피해를 입히고, 성전사의 일격 효과가 중첩된 만큼 적이 입는 신성 피해를 증가시킵니다. 최대 5번까지 중첩될 수 있습니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={{31,109853475},"받는 신성 피해 증가"}}
